    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    fg = next(v for v in counts if v != bg)
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Bridge short gaps between consecutive aligned foreground cells in color 2.
    # Demos show bridges spanning as many as six blank cells (endpoint distance 7).
    max_distance = 7
    for r in range(h):
        positions = [c for c in range(w) if grid[r][c] == fg]
        for a, b in zip(positions, positions[1:]):
            if 1 < b - a <= max_distance:
                for c in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == fg]
        for a, b in zip(positions, positions[1:]):
            if 1 < b - a <= max_distance:
                for r in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    return out

